using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query.Execution;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.CrossDomain;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Graph;using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationIntegrationTests{[Fact]public void Resolves_all_representative_services_and_preserves_catalog_query_contracts(){var f=new KnowledgeFoundationIntegrationFixture();Assert.IsAssignableFrom<IAstronomyTypedPayloadRegistry>(f.Provider.GetRequiredService<IAstronomyTypedPayloadRegistry>());Assert.IsAssignableFrom<IAstronomyKnowledgeValidationRuleRegistry>(f.Provider.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>());Assert.IsAssignableFrom<IAstronomyCrossDomainValidationRuleRegistry>(f.Provider.GetRequiredService<IAstronomyCrossDomainValidationRuleRegistry>());var graph=f.Provider.GetRequiredService<IAstronomyKnowledgeGraphValidationRuleRegistry>();Assert.Equal(11,graph.Descriptors.Count);Assert.Equal(11,f.Catalog.Snapshot.GraphValidationRules.Count);Assert.IsAssignableFrom<IAstronomyKnowledgeCatalog>(f.Catalog);Assert.IsAssignableFrom<IAstronomyKnowledgeQueryValidator>(f.QueryValidator);Assert.IsAssignableFrom<IAstronomyKnowledgeCatalogQueryEngine>(f.CatalogEngine);Assert.IsAssignableFrom<IAstronomyKnowledgeStatementQueryEngine>(f.StatementEngine);Assert.IsAssignableFrom<IAstronomyKnowledgeFoundationCapabilities>(f.Capabilities);Assert.IsAssignableFrom<IAstronomyKnowledgeFoundationCompatibilityVerifier>(f.Verifier);Assert.True(f.Catalog.TryGet(f.Catalog.Snapshot.KnowledgeTypes.First().Id,out var exact));Assert.Equal(exact.Id,f.CatalogEngine.Execute(new AstronomyKnowledgeCatalogQuery(entryIds:[exact.Id])).Items.Single().Id);Assert.True(f.Verifier.Verify().IsCompatible);}}
